import java.io.*;
import java.util.*;

public class J implements Runnable {

    private static final boolean ONLINE_JUDGE = System.getProperty("ONLINE_JUDGE") != null;

    private BufferedReader br;
    private PrintWriter pw;
    private StringTokenizer st = new StringTokenizer("");

    private void setupIO() throws FileNotFoundException {
        Locale.setDefault(Locale.US);
        String filename = "";
        if (ONLINE_JUDGE && filename.isEmpty()) {
            br = new BufferedReader(new InputStreamReader(System.in));
            pw = new PrintWriter(System.out);
        } else {
            if (filename.isEmpty()) {
                br = new BufferedReader(new FileReader("input.txt"));
                pw = new PrintWriter(new FileWriter("output.txt"));
            } else {
                br = new BufferedReader(new FileReader(filename + ".in"));
                pw = new PrintWriter(new FileWriter(filename + ".out"));
            }
        }
    }

    String nextToken() throws IOException {
        while (!st.hasMoreTokens()) {
            st = new StringTokenizer(br.readLine());
        }
        return st.nextToken();
    }

    int nextInt() throws IOException {
        return Integer.parseInt(nextToken());
    }

    long nextLong() throws IOException {
        return Long.parseLong(nextToken());
    }

    double nextDouble() throws IOException {
        return Double.parseDouble(nextToken());
    }

    int[] readInts(int size) throws IOException {
        int[] arr = new int[size];
        for (int i = 0; i < size; i++) {
            arr[i] = nextInt();
        }
        return arr;
    }

    public static void main(String[] args) {
        new J().run();
    }

    long startTime, endTime;

    void measure() {
        endTime = System.currentTimeMillis();
        System.err.println("Time elapsed: " + (endTime - startTime));
    }

    @Override
    public void run() {
        try {
            startTime = System.currentTimeMillis();
            setupIO();
            process();
            pw.close();
            measure();
        } catch (Exception e) {
            e.printStackTrace();
            System.exit(-1);
        }
    }

    int[][][][] dp;
    char[] seq;
    int INF = 10000000;

    int calcCost(char[] arr, char target, int v, int k, int x) {
        int cost = 0;
        for (char c : arr) {
            if (c == 'V') {
                v--;
                if (v == 0 && target == 'V') return cost;
                if (v < 0) cost++;
            }
            if (c == 'K') {
                k--;
                if (k == 0 && target == 'K') return cost;
                if (k < 0) cost++;
            }
            if (c == 'X') {
                x--;
                if (x == 0 && target == 'X') return cost;
                if (x < 0) cost++;
            }
        }
        throw new RuntimeException();
    }

    private void process() throws IOException {
        int n = nextInt();
        seq = nextToken().toCharArray();
        int vCount = 0, kCount = 0, xCount = 0;
        for (int i = 0; i < seq.length; i++) {
            if (seq[i] == 'V') vCount++;
            else if (seq[i] == 'K') kCount++;
            else {
                seq[i] = 'X';
                xCount++;
            }
        }
        dp = new int[vCount + 1][kCount + 1][xCount + 1][3];
        for (int[][][] arr3d : dp) {
            for (int[][] arr2d : arr3d) {
                for (int[] arr1d : arr2d) {
                    Arrays.fill(arr1d, INF);
                }
            }
        }
        for (int i = 0; i < 3; i++) {
            dp[0][0][0][i] = 0;
        }
        for (int v = 0; v <= vCount; v++) {
            for (int k = 0; k <= kCount; k++) {
                for (int x = 0; x <= xCount; x++) {
                    for (int prev = 0; prev < 3; prev++) {
                        int currentCost = dp[v][k][x][prev];
                        if (currentCost == INF) continue;
                        if (v + 1 <= vCount) {
                            int cst = calcCost(seq, 'V', v + 1, k, x);
                            dp[v + 1][k][x][0] = Math.min(dp[v + 1][k][x][0], currentCost + cst);
                        }
                        if (k + 1 <= kCount) {
                            int cst = calcCost(seq, 'K', v, k + 1, x);
                            if (prev != 0) {
                                dp[v][k + 1][x][1] = Math.min(dp[v][k + 1][x][1], currentCost + cst);
                            }
                        }
                        if (x + 1 <= xCount) {
                            int cst = calcCost(seq, 'X', v, k, x + 1);
                            dp[v][k][x + 1][2] = Math.min(dp[v][k][x + 1][2], currentCost + cst);
                        }
                    }
                }
            }
        }
        int answer = INF;
        for (int i = 0; i < 3; i++) {
            answer = Math.min(answer, dp[vCount][kCount][xCount][i]);
        }
        pw.println(answer);
    }
}
